"""CPU tests for the candidates: generated by a fake agent, run and labelled on the tiny
network and synthetic data."""

import json
import tempfile
import types
import unittest
import warnings
from pathlib import Path
from unittest.mock import patch

# The module, not its classes: a TestCase imported here would run here as well.
import test_pipeline_tasks
from test_pipeline_workspace import write_project

from runsleuth import pipeline_tasks
from runsleuth.pipeline_tasks import HEALTHY

try:
    import torch
except ModuleNotFoundError as error:
    if error.name != "torch":
        raise
    torch = None

if torch is not None:
    from runsleuth import candidates, challenge_set, pipeline_contract, pipeline_workspace

STARTS = ("positions_index_base", "checkpoint_in_parts")
SYNTHETIC = {"camelyon_pipeline": ("synthetic", None), "ham10000_pipeline": ("synthetic_ham", None)}


def subset():
    """Two development starting versions: two agent repetitions and the version as it is."""
    return [
        candidate
        for candidate in challenge_set.plan("development")
        if candidate.start in STARTS and (candidate.repetition or 1) <= 2
    ]


def run_in_process(project, run_dir, *, data, config, epochs, seed, device, **options):
    path = pipeline_workspace.run_project(
        project,
        run_dir,
        pipeline_workspace.data_builder(data, config, options.get("max_eval_samples")),
        epochs=epochs,
        seed=seed,
        device=torch.device("cpu"),
        interrupt_after_epochs=options.get("interrupt_after_epochs"),
    )
    status = json.loads(Path(path).read_text(encoding="utf-8"))["status"]
    return {"status": status, "problems": [], "report": str(path), "error": None, "output": ""}


class FakeAgent:
    """Trains once, then finishes claiming the project is correct; or fails with an error."""

    def __init__(self, error=None):
        self.error, self.calls = error, 0
        self.chat = types.SimpleNamespace(completions=types.SimpleNamespace(create=self.create))

    def create(self, **request):
        self.calls += 1
        if self.error is not None:
            raise self.error
        trained = any(message["role"] == "tool" for message in request["messages"])
        name, arguments = (
            ("finish", {"project_is_correct": True, "problem": "none", "summary": "fine"})
            if trained
            else ("run_training", {})
        )
        call = types.SimpleNamespace(
            id=f"call-{self.calls}",
            function=types.SimpleNamespace(name=name, arguments=json.dumps(arguments)),
        )
        message = types.SimpleNamespace(content="", tool_calls=[call])
        return types.SimpleNamespace(
            choices=[types.SimpleNamespace(message=message)], usage=None, model="fake-1"
        )


class RejectedError(Exception):
    status_code = 400


@unittest.skipIf(torch is None, "Install torch and torchvision for the pipeline tests")
class CandidateTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        for patcher in (
            patch("runsleuth.pipeline_tasks.version_sources", test_pipeline_tasks.tiny_version),
            patch.object(candidates, "candidates", lambda _split: subset()),
        ):
            patcher.start()
            self.addCleanup(patcher.stop)
        self.trained = []

        def counted(*arguments, **options):
            self.trained.append(options)
            return run_in_process(*arguments, **options)

        self.short_runs = candidates.Runner(self.root / "short", data=SYNTHETIC, run=counted)

    def generate(self, client):
        return candidates.generate(
            "development",
            "gemini-3.5-flash-lite",
            client,
            "fake",
            root=self.root / "candidates",
            workspaces=self.root / "workspaces",
            runner=self.short_runs,
            progress=lambda _line: None,
        )

    def test_agents_work_in_neutral_folders_and_identical_short_runs_train_once(self):
        written = self.generate(FakeAgent())
        self.assertEqual(len(written), 4)
        self.assertTrue(all(e["record"]["status"] == "finished" for e in written))
        # Two starting versions, two repetitions on one seed: two short runs.
        self.assertEqual(len(self.trained), 2)
        self.assertEqual(self.trained[0]["epochs"], 2)
        self.assertEqual(self.trained[0]["max_eval_samples"], 1000)
        for path in (self.root / "workspaces").rglob("*"):
            relative = str(path.relative_to(self.root / "workspaces"))
            for word in (*STARTS, "development", "test", "camelyon"):
                self.assertNotIn(word, relative)
        # Finished episodes are not repeated.
        self.assertEqual(self.generate(FakeAgent()), [])

    def test_an_episode_that_ended_in_an_api_error_is_tried_again_in_a_new_folder(self):
        failed = self.generate(FakeAgent(RejectedError("bad request")))
        self.assertTrue(all(e["record"]["status"] == "api_error" for e in failed))
        again = self.generate(FakeAgent())
        self.assertEqual([e["attempt"] for e in again], [2, 2, 2, 2])
        folders = {path.name for path in (self.root / "workspaces").glob("*/attempt-*")}
        self.assertEqual(folders, {"attempt-1", "attempt-2"})

    def test_candidates_are_run_against_references_and_labelled_by_the_hidden_tests(self):
        self.generate(FakeAgent())
        runner = candidates.Runner(self.root / "runs", data=SYNTHETIC, run=run_in_process)
        runs = candidates.run_all(
            "development", root=self.root / "candidates", runner=runner, progress=lambda _: None
        )
        self.assertEqual(list(runs["references"]), ["camelyon_pipeline/7"])
        self.assertEqual(len(runs["runs"]), 6)
        self.assertTrue(all(outcome["status"] == "completed" for outcome in runs["runs"].values()))
        # version_sources is the tiny network's here, so is the healthy project.
        healthy = write_project(self.root / "healthy", pipeline_tasks.version_sources(HEALTHY))

        def contract(project, family):
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", UserWarning)
                return pipeline_contract.run_contract(project, family, healthy)

        labels = candidates.label_all(
            "development", root=self.root / "candidates", contract=contract, progress=lambda _: None
        )["labels"]
        self.assertEqual(len(labels), 6)
        for candidate_id, label in labels.items():
            start = candidate_id.split("/")[1]
            expected = "wrong" if start == "positions_index_base" else "correct"
            self.assertEqual(label["label"], expected, candidate_id)
        self.assertTrue((self.root / "candidates" / "development" / "labels.json").exists())


if __name__ == "__main__":
    unittest.main()
